// Rota Perfeita — Google Maps Street-Level Real-Time, Física Real de Movimento (m/s), Inspeção IA e CarPlay por Motorista

function calcRouteCost({ km, dieselPrice, baseKmL, loadTons, maxTons, slopeIdx = 0.15, toll = 0, driverCost = 0, transshipment = 0, backhaulRevenue = 0 }) {
  const loadFactor = 1 + 0.28 * (loadTons / maxTons) + 0.12 * slopeIdx;
  const fuelPerKm = (dieselPrice / baseKmL) * loadFactor;
  const total = km * (fuelPerKm + 0.92) + toll + driverCost + transshipment - backhaulRevenue;
  return { total, perKm: total / km };
}

function calcRiskScore({ crimeIdx, weatherIdx, cargoValIdx, fatigueIdx, shadowIdx }) {
  return Math.min(100, Math.round(100 * (0.35 * crimeIdx + 0.25 * weatherIdx + 0.20 * cargoValIdx + 0.10 * fatigueIdx + 0.10 * shadowIdx)));
}

function decodeGooglePolyline(encoded) {
  const points = [];
  let index = 0, lat = 0, lng = 0;
  while (index < encoded.length) {
    let b, shift = 0, result = 0;
    do { b = encoded.charCodeAt(index++) - 63; result |= (b & 0x1f) << shift; shift += 5; } while (b >= 0x20);
    lat += result & 1 ? ~(result >> 1) : result >> 1;
    shift = 0; result = 0;
    do { b = encoded.charCodeAt(index++) - 63; result |= (b & 0x1f) << shift; shift += 5; } while (b >= 0x20);
    lng += result & 1 ? ~(result >> 1) : result >> 1;
    points.push([lat / 1e5, lng / 1e5]);
  }
  return points;
}

// Distância geodésica exata em metros (Haversine) para velocidade física realista em km/h
function haversineMeters([lat1, lon1], [lat2, lon2]) {
  const R = 6371000;
  const toRad = (d) => (d * Math.PI) / 180;
  const dLat = toRad(lat2 - lat1);
  const dLon = toRad(lon2 - lon1);
  const a = Math.sin(dLat / 2) ** 2 + Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLon / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(a));
}

function lerpAngle(currentDeg, targetDeg, factor) {
  const diff = ((((targetDeg - currentDeg) % 360) + 540) % 360) - 180;
  return (currentDeg + diff * factor + 360) % 360;
}

function buildArcMetrics(pts) {
  const cum = [0];
  for (let i = 1; i < pts.length; i++) {
    cum.push(cum[i - 1] + Math.max(1, haversineMeters(pts[i - 1], pts[i])));
  }
  return { cum, totalMeters: cum[cum.length - 1] || 1 };
}

function samplePolylineAtMeters(pts, arc, distMeters) {
  if (!pts || pts.length < 2) return { lat: -23.52, lng: -46.57, heading: 45, segIndex: 0 };
  const clamped = Math.max(0, Math.min(arc.totalMeters - 0.5, distMeters));
  let lo = 0, hi = arc.cum.length - 2;
  while (lo < hi) {
    const mid = (lo + hi + 1) >> 1;
    if (arc.cum[mid] <= clamped) lo = mid;
    else hi = mid - 1;
  }
  const segStart = arc.cum[lo];
  const segLen = Math.max(1, arc.cum[lo + 1] - segStart);
  const frac = (clamped - segStart) / segLen;
  const [lat1, lng1] = pts[lo];
  const [lat2, lng2] = pts[lo + 1];
  const lat = lat1 + (lat2 - lat1) * frac;
  const lng = lng1 + (lng2 - lng1) * frac;
  const dy = lat2 - lat1;
  const dx = (lng2 - lng1) * Math.cos((lat * Math.PI) / 180);
  const heading = ((Math.atan2(dx, dy) * 180) / Math.PI + 360) % 360;
  return { lat, lng, heading, segIndex: lo };
}

