function mountIcons() {
  document.querySelectorAll('[data-icon]').forEach((el) => {
    const key = el.getAttribute('data-icon');
    const size = el.getAttribute('data-size') || '18';
    el.innerHTML = `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${svgIcons[key] || '<circle cx="12" cy="12" r="8"/>'}</svg>`;
  });
}

// ==================== PROJEÇÃO WEB MERCATOR & MOTOR GOOGLE MAPS STREET-LEVEL ====================
function latLngToWorld(lat, lng, zoom) {
  const scale = 256 * Math.pow(2, zoom);
  const clampedLat = Math.max(-85.0511, Math.min(85.0511, lat));
  const sinLat = Math.sin((clampedLat * Math.PI) / 180);
  return {
    x: ((lng + 180) / 360) * scale,
    y: (0.5 - Math.log((1 + sinLat) / (1 - sinLat)) / (4 * Math.PI)) * scale
  };
}

function worldToLatLng(wx, wy, zoom) {
  const scale = 256 * Math.pow(2, zoom);
  const lng = (wx / scale) * 360 - 180;
  const n = Math.PI - (2 * Math.PI * wy) / scale;
  const lat = (180 / Math.PI) * Math.atan(0.5 * (Math.exp(n) - Math.exp(-n)));
  return { lat: Math.max(-85, Math.min(85, lat)), lng: ((((lng + 180) % 360) + 360) % 360) - 180 };
}

class GoogleRealtimeSlippyMap {
  constructor({ stageId, canvasId, tilesId, svgId, centerLat, centerLng, zoom, isCarPlay = false }) {
    this.stage = document.getElementById(stageId);
    this.canvas = document.getElementById(canvasId);
    this.tilesEl = document.getElementById(tilesId);
    this.svgEl = document.getElementById(svgId);
    this.centerLat = centerLat;
    this.centerLng = centerLng;
    this.zoom = zoom;
    this.mode = 'road';
    this.traffic = true;
    this.isCarPlay = isCarPlay;
    this.tileCache = new Map();
    this.loadedTilesCount = 0;
    this.dragging = false;
    this.lastX = 0;
    this.lastY = 0;
    this.bindEvents();
  }

  bindEvents() {
    this.stage.addEventListener('pointerdown', (e) => {
      if (e.target.closest('[data-truck-click]')) return;
      this.dragging = true;
      this.lastX = e.clientX;
      this.lastY = e.clientY;
      this.stage.setPointerCapture(e.pointerId);
      if (this.isCarPlay) state.followCarPlay = false;
      else {
        state.followTower = false;
        const chip = document.getElementById('chipFollowTower');
        if (chip) chip.classList.remove('active');
      }
    });

    this.stage.addEventListener('pointermove', (e) => {
      if (!this.dragging) return;
      const dx = e.clientX - this.lastX;
      const dy = e.clientY - this.lastY;
      this.lastX = e.clientX;
      this.lastY = e.clientY;
      const c = latLngToWorld(this.centerLat, this.centerLng, this.zoom);
      const next = worldToLatLng(c.x - dx, c.y - dy, this.zoom);
      this.centerLat = next.lat;
      this.centerLng = next.lng;
      this.render();
    });

    const stopDrag = () => { this.dragging = false; };
    this.stage.addEventListener('pointerup', stopDrag);
    this.stage.addEventListener('pointercancel', stopDrag);

    this.stage.addEventListener('wheel', (e) => {
      e.preventDefault();
      this.setZoom(this.zoom + (e.deltaY < 0 ? 1 : -1));
    }, { passive: false });
  }

  setZoom(nextZoom) {
    const clamped = Math.max(4, Math.min(17, Math.round(nextZoom)));
    if (clamped === this.zoom) return;
    this.zoom = clamped;
    this.clearTilesDom();
    this.render();
  }

  setCenter(lat, lng, zoom = null) {
    this.centerLat = lat;
    this.centerLng = lng;
    if (zoom !== null && zoom !== this.zoom) {
      this.zoom = Math.max(4, Math.min(17, Math.round(zoom)));
      this.clearTilesDom();
    }
    this.render();
  }

  clearTilesDom() {
    this.tileCache.clear();
    this.tilesEl.innerHTML = '';
  }

  getLyrsCode() {
    if (this.mode === 'satellite') return this.traffic ? 'y,traffic' : 'y';
    if (this.mode === 'terrain') return this.traffic ? 'p,traffic' : 'p';
    return this.traffic ? 'm,traffic' : 'm';
  }

  render() {
    const W = this.stage.clientWidth || 760;
    const H = this.stage.clientHeight || 480;
    const z = this.zoom;
    const maxTile = Math.pow(2, z);
    const centerW = latLngToWorld(this.centerLat, this.centerLng, z);
    const topLeftX = centerW.x - W / 2;
    const topLeftY = centerW.y - H / 2;

    this.renderStreetAndNationalBase(W, H, z, topLeftX, topLeftY);
    this.renderGoogleTiles(W, H, z, maxTile, topLeftX, topLeftY);
    this.renderOverlaySvg(W, H, z, topLeftX, topLeftY);
  }

  // Malha Cartográfica Urbana + Rodoviária Padrão Google Maps (Exibe quadras, ruas, avenidas e nomes se offline/sandbox)
  renderStreetAndNationalBase(W, H, z, topLeftX, topLeftY) {
    if (this.canvas.width !== W || this.canvas.height !== H) {
      this.canvas.width = W;
      this.canvas.height = H;
    }
    const ctx = this.canvas.getContext('2d');
    const isSat = this.mode === 'satellite';

    if (z >= 11) {
      // Fundo Urbano Padrão Google Maps (Quadras #f1f3f4, Parques #ceead6, Ruas #ffffff, Avenidas #fde293)
      ctx.fillStyle = isSat ? '#152a1e' : '#eaecef';
      ctx.fillRect(0, 0, W, H);

      const gridStep = z >= 15 ? 92 : z >= 13 ? 64 : 44;
      const startGx = Math.floor(topLeftX / gridStep) * gridStep;
      const startGy = Math.floor(topLeftY / gridStep) * gridStep;

      // Quadras e Áreas Verdes Urbanas
      for (let gx = startGx; gx < topLeftX + W + gridStep; gx += gridStep) {
        for (let gy = startGy; gy < topLeftY + H + gridStep; gy += gridStep) {
          const hash = Math.abs(Math.sin(gx * 0.013 + gy * 0.017));
          const sx = gx - topLeftX;
          const sy = gy - topLeftY;
          if (hash > 0.84) {
            ctx.fillStyle = isSat ? '#1b3f29' : '#ceead6';
            ctx.fillRect(sx + 6, sy + 6, gridStep - 12, gridStep - 12);
          } else {
            ctx.fillStyle = isSat ? '#1d2d3a' : '#f8f9fa';
            ctx.fillRect(sx + 5, sy + 5, gridStep - 10, gridStep - 10);
          }
        }
      }

      // Ruas Locais (Casings #dadce0 + Leito Branco #ffffff) e Avenidas Arteriais (#fde293)
      for (let gx = startGx; gx < topLeftX + W + gridStep; gx += gridStep) {
        const sx = Math.round(gx - topLeftX);
        const isArterial = Math.abs(Math.round(gx / gridStep)) % 4 === 0;
        ctx.strokeStyle = isSat ? 'rgba(255,255,255,0.22)' : isArterial ? '#fbbc04' : '#dadce0';
        ctx.lineWidth = isArterial ? (z >= 14 ? 11 : 7) : (z >= 14 ? 7 : 4);
        ctx.beginPath(); ctx.moveTo(sx, 0); ctx.lineTo(sx, H); ctx.stroke();

        ctx.strokeStyle = isSat ? 'rgba(255,255,255,0.35)' : isArterial ? '#fef08a' : '#ffffff';
        ctx.lineWidth = isArterial ? (z >= 14 ? 8 : 5) : (z >= 14 ? 5 : 2.5);
        ctx.beginPath(); ctx.moveTo(sx, 0); ctx.lineTo(sx, H); ctx.stroke();
      }

      for (let gy = startGy; gy < topLeftY + H + gridStep; gy += gridStep) {
        const sy = Math.round(gy - topLeftY);
        const isArterial = Math.abs(Math.round(gy / gridStep)) % 4 === 0;
        ctx.strokeStyle = isSat ? 'rgba(255,255,255,0.22)' : isArterial ? '#fbbc04' : '#dadce0';
        ctx.lineWidth = isArterial ? (z >= 14 ? 11 : 7) : (z >= 14 ? 7 : 4);
        ctx.beginPath(); ctx.moveTo(0, sy); ctx.lineTo(W, sy); ctx.stroke();

        ctx.strokeStyle = isSat ? 'rgba(255,255,255,0.35)' : isArterial ? '#fef08a' : '#ffffff';
        ctx.lineWidth = isArterial ? (z >= 14 ? 8 : 5) : (z >= 14 ? 5 : 2.5);
        ctx.beginPath(); ctx.moveTo(0, sy); ctx.lineTo(W, sy); ctx.stroke();
      }

      // Desenha os Corredores Rodoviários Reais em Destaque
      fleet.forEach((tr) => {
        ctx.beginPath();
        tr.waypoints.forEach(([lat, lng], idx) => {
          const p = latLngToWorld(lat, lng, z);
          if (idx === 0) ctx.moveTo(p.x - topLeftX, p.y - topLeftY);
          else ctx.lineTo(p.x - topLeftX, p.y - topLeftY);
        });
        ctx.strokeStyle = '#e37400';
        ctx.lineWidth = z >= 14 ? 15 : 10;
        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';
        ctx.stroke();

        ctx.strokeStyle = '#fde293';
        ctx.lineWidth = z >= 14 ? 11 : 7;
        ctx.stroke();
      });

      // Rótulos Reais das Ruas e Rodovias do Caminhão Selecionado
      const selTr = fleet.find((i) => i.id === state.selectedTruckId) || fleet[0];
      ctx.font = '700 12px "IBM Plex Sans", sans-serif';
      selTr.steps.forEach((st) => {
        const p = latLngToWorld(st.loc[0], st.loc[1], z);
        const px = p.x - topLeftX;
        const py = p.y - topLeftY;
        if (px > 10 && px < W - 120 && py > 20 && py < H - 20) {
          ctx.fillStyle = isSat ? 'rgba(9,16,24,0.82)' : 'rgba(255,255,255,0.9)';
          const tw = Math.min(240, ctx.measureText(st.road).width + 12);
          ctx.fillRect(px + 8, py - 11, tw, 18);
          ctx.fillStyle = isSat ? '#f8fafc' : '#202124';
          ctx.fillText(st.road, px + 14, py + 2);
        }
      });
      return;
    }

    // Visão Regional / Brasil (z < 11)
    ctx.fillStyle = isSat ? '#082032' : '#aadaff';
    ctx.fillRect(0, 0, W, H);

    ctx.beginPath();
    BRAZIL_BORDER_COORDS.forEach(([lat, lng], idx) => {
      const p = latLngToWorld(lat, lng, z);
      if (idx === 0) ctx.moveTo(p.x - topLeftX, p.y - topLeftY);
      else ctx.lineTo(p.x - topLeftX, p.y - topLeftY);
    });
    ctx.closePath();
    ctx.fillStyle = isSat ? '#183626' : '#f5f3f0';
    ctx.fill();
    ctx.strokeStyle = isSat ? '#4f7c63' : '#bdc1c6';
    ctx.lineWidth = 1.5;
    ctx.stroke();

    fleet.forEach((tr) => {
      ctx.beginPath();
      tr.waypoints.forEach(([lat, lng], idx) => {
        const p = latLngToWorld(lat, lng, z);
        if (idx === 0) ctx.moveTo(p.x - topLeftX, p.y - topLeftY);
        else ctx.lineTo(p.x - topLeftX, p.y - topLeftY);
      });
      ctx.strokeStyle = '#fbbc04';
      ctx.lineWidth = z >= 7 ? 3.5 : 2.2;
      ctx.stroke();
    });

    ctx.font = '600 12px "IBM Plex Sans", sans-serif';
    ctx.fillStyle = isSat ? '#ffffff' : '#3c4043';
    BRAZIL_CITIES.forEach(([lat, lng, name]) => {
      const p = latLngToWorld(lat, lng, z);
      const px = p.x - topLeftX, py = p.y - topLeftY;
      if (px > -50 && px < W + 50 && py > -20 && py < H + 20) {
        ctx.beginPath(); ctx.arc(px, py, 2.5, 0, Math.PI * 2); ctx.fill();
        ctx.fillText(name, px + 6, py + 4);
      }
    });
  }

  renderGoogleTiles(W, H, z, maxTile, topLeftX, topLeftY) {
    const minTx = Math.floor(topLeftX / 256) - 1;
    const maxTx = Math.floor((topLeftX + W) / 256) + 1;
    const minTy = Math.max(0, Math.floor(topLeftY / 256) - 1);
    const maxTy = Math.min(maxTile - 1, Math.floor((topLeftY + H) / 256) + 1);
    const lyrs = this.getLyrsCode();
    const tb = Math.floor(Date.now() / 60000);
    const neededKeys = new Set();

    for (let tx = minTx; tx <= maxTx; tx++) {
      for (let ty = minTy; ty <= maxTy; ty++) {
        const wrappedTx = ((tx % maxTile) + maxTile) % maxTile;
        const key = `${lyrs}:${z}:${tx}:${ty}:${tb}`;
        neededKeys.add(key);

        let img = this.tileCache.get(key);
        if (!img) {
          img = document.createElement('img');
          const sub = Math.abs(wrappedTx + ty) % 4;
          img.src = `https://mt${sub}.google.com/vt/lyrs=${lyrs}&hl=pt-BR&gl=BR&x=${wrappedTx}&y=${ty}&z=${z}&_tb=${tb}`;
          img.alt = '';
          img.decoding = 'async';
          img.style.cssText = 'position:absolute;width:256px;height:256px;pointer-events:none;';
          img.onload = () => { this.loadedTilesCount++; };
          img.onerror = () => { img.style.display = 'none'; };
          this.tilesEl.appendChild(img);
          this.tileCache.set(key, img);
        }
        img.style.left = `${Math.round(tx * 256 - topLeftX)}px`;
        img.style.top = `${Math.round(ty * 256 - topLeftY)}px`;
      }
    }

    for (const [key, img] of this.tileCache.entries()) {
      if (!neededKeys.has(key)) {
        img.remove();
        this.tileCache.delete(key);
      }
    }
  }

  // Desenha Trajeto Percorrido (Cinza), Rota Ativa à Frente (#4285F4 Google Blue + Setas), Manobras e Caminhão do Motorista
  renderOverlaySvg(W, H, z, topLeftX, topLeftY) {
    this.svgEl.setAttribute('viewBox', `0 0 ${W} ${H}`);
    const toPx = ([lat, lng]) => {
      const w = latLngToWorld(lat, lng, z);
      return [w.x - topLeftX, w.y - topLeftY];
    };
    const polyD = (pts) =>
      pts.map((pt, i) => {
        const [x, y] = toPx(pt);
        return `${i === 0 ? 'M' : 'L'}${x.toFixed(1)},${y.toFixed(1)}`;
      }).join(' ');

    const selTr = fleet.find((i) => i.id === state.selectedTruckId) || fleet[0];
    const curSample = samplePolylineAtMeters(selTr.waypoints, selTr.arc, selTr.traveledMeters);
    const curPt = [curSample.lat, curSample.lng];

    const traveledPts = selTr.waypoints.slice(0, curSample.segIndex + 1).concat([curPt]);
    const remainingPts = [curPt].concat(selTr.waypoints.slice(curSample.segIndex + 1));

    const svgParts = [];

    // Se Risco ativo e CAM-01 selecionado, mostra o trecho interditado em vermelho tracejado
    if (state.riskActive && selTr.id === 'CAM-01') {
      const blockedD = polyD(selTr.baseWaypoints);
      svgParts.push(`<path d="${blockedD}" fill="none" stroke="#a50e0e" stroke-width="8" stroke-linecap="round" opacity="0.75"/>`);
      svgParts.push(`<path d="${blockedD}" fill="none" stroke="#ea4335" stroke-width="5" stroke-dasharray="8 6" stroke-linecap="round"/>`);
    }

    // 1. Trajeto já percorrido pelo caminhão selecionado
    if (traveledPts.length > 1) {
      svgParts.push(`<path d="${polyD(traveledPts)}" fill="none" stroke="#5f6368" stroke-width="${this.isCarPlay ? 10 : 7}" stroke-linecap="round" stroke-linejoin="round" opacity="0.75"/>`);
    }

    // 2. Rota Ativa à Frente (Azul Oficial Google Maps #4285F4 com Borda #185ABC)
    if (remainingPts.length > 1) {
      const remD = polyD(remainingPts);
      svgParts.push(`<path d="${remD}" fill="none" stroke="#185abc" stroke-width="${this.isCarPlay ? 13 : 9}" stroke-linecap="round" stroke-linejoin="round"/>`);
      svgParts.push(`<path d="${remD}" fill="none" stroke="#4285f4" stroke-width="${this.isCarPlay ? 8.5 : 5.5}" stroke-linecap="round" stroke-linejoin="round"/>`);

      // Setas brancas direcionais sobre o trajeto no modo Rua/CarPlay
      if (z >= 12) {
        let lastArrowX = -999, lastArrowY = -999;
        for (let i = 0; i < remainingPts.length - 1; i++) {
          const [x1, y1] = toPx(remainingPts[i]);
          const [x2, y2] = toPx(remainingPts[i + 1]);
          const mx = (x1 + x2) / 2, my = (y1 + y2) / 2;
          if (mx > 0 && mx < W && my > 0 && my < H && Math.hypot(mx - lastArrowX, my - lastArrowY) > 85) {
            const ang = (Math.atan2(y2 - y1, x2 - x1) * 180) / Math.PI;
            svgParts.push(`<g transform="translate(${mx.toFixed(1)},${my.toFixed(1)}) rotate(${ang.toFixed(1)})"><polygon points="5,0 -4,-4 -2,0 -4,4" fill="#ffffff"/></g>`);
            lastArrowX = mx; lastArrowY = my;
          }
        }
      }

      // Pino Vermelho Google no Destino Final da Rota do Caminhão
      const [dx, dy] = toPx(remainingPts[remainingPts.length - 1]);
      svgParts.push(`
        <g transform="translate(${dx.toFixed(1)}, ${dy.toFixed(1)})">
          <path d="M0,0 C-7,-10 -11,-15 -11,-21 A11,11 0 1,1 11,-21 C11,-15 7,-10 0,0 Z" fill="#ea4335" stroke="#ffffff" stroke-width="1.5"/>
          <circle cx="0" cy="-21" r="4" fill="#800000"/>
        </g>`);
    }

    // 3. Pontos de Manobra de Rua (Steps) no CarPlay
    if (this.isCarPlay && z >= 13) {
      selTr.steps.forEach((st) => {
        const [sx, sy] = toPx(st.loc);
        if (sx > 10 && sx < W - 10 && sy > 10 && sy < H - 10) {
          svgParts.push(`<circle cx="${sx.toFixed(1)}" cy="${sy.toFixed(1)}" r="4.5" fill="#ffffff" stroke="#185abc" stroke-width="2"/>`);
        }
      });
    }

    // 4. Zona de Risco 22h
    if (state.showRisk || state.riskActive) {
      const [rx, ry] = toPx([-22.665, -43.862]);
      svgParts.push(`
        <g transform="translate(${rx.toFixed(1)}, ${ry.toFixed(1)})">
          <circle cx="0" cy="0" r="24" fill="#ea4335" fill-opacity="0.25" stroke="#d93025" stroke-width="2"/>
          <circle cx="0" cy="0" r="9" fill="#d93025" stroke="#ffffff" stroke-width="1.8"/>
          <line x1="-4.5" y1="0" x2="4.5" y2="0" stroke="#ffffff" stroke-width="2.5"/>
        </g>`);
    }

    // 5. Hubs na Visão da Torre
    if (state.showHubs && !this.isCarPlay) {
      const hubs = [
        [-22.4705, -44.4509, 'Hub Km 120'],
        [-23.4543, -46.5337, 'Hub VUC SP'],
        [-18.9186, -48.2772, 'Coleta 18t']
      ];
      hubs.forEach(([lat, lng, label]) => {
        const [hx, hy] = toPx([lat, lng]);
        if (hx > -50 && hx < W + 50 && hy > -30 && hy < H + 30) {
          svgParts.push(`
            <g transform="translate(${hx.toFixed(1)}, ${hy.toFixed(1)})">
              <rect x="-38" y="-24" width="76" height="19" rx="5" fill="#1967d2" stroke="#ffffff" stroke-width="1.4"/>
              <text x="0" y="-11" text-anchor="middle" fill="#ffffff" font-size="12" font-weight="700">${label}</text>
            </g>`);
        }
      });
    }

    // 6. Puck de Localização Atual no Multimídia CarPlay vs Frota Completa na Torre
    if (this.isCarPlay) {
      const [px, py] = toPx(curPt);
      svgParts.push(`
        <g transform="translate(${px.toFixed(1)}, ${py.toFixed(1)})">
          <circle cx="0" cy="0" r="30" fill="#4285f4" fill-opacity="0.20"/>
          <circle cx="0" cy="0" r="16" fill="#ffffff" stroke="#185abc" stroke-width="2"/>
          <g transform="rotate(${selTr.smoothHeading.toFixed(1)})">
            <polygon points="0,-10 8,8 0,4 -8,8" fill="#1a73e8"/>
          </g>
          <rect x="-52" y="21" width="104" height="20" rx="6" fill="#0f172a" stroke="#38bdf8" stroke-width="1.2"/>
          <text x="0" y="35" text-anchor="middle" fill="#ffffff" font-size="12" font-weight="700">${selTr.id} · ${Math.round(selTr.liveSpeed)} km/h</text>
        </g>`);
    } else {
      fleet.forEach((tr) => {
        const pos = samplePolylineAtMeters(tr.waypoints, tr.arc, tr.traveledMeters);
        const [px, py] = toPx([pos.lat, pos.lng]);
        if (px < -60 || px > W + 60 || py < -40 || py > H + 40) return;
        const color = statusColors[tr.status] || '#188038';
        const isSel = tr.id === state.selectedTruckId;
        const halo = isSel ? `<circle cx="0" cy="0" r="18" fill="#4285f4" fill-opacity="0.28" stroke="#1a73e8" stroke-width="2"/>` : '';
        svgParts.push(`
          <g data-truck-click="${tr.id}" transform="translate(${px.toFixed(1)}, ${py.toFixed(1)})" style="cursor:pointer" onclick="selectTruck('${tr.id}')">
            ${halo}
            <circle cx="0" cy="0" r="11" fill="#ffffff" stroke="${color}" stroke-width="2.5"/>
            <g transform="rotate(${tr.smoothHeading.toFixed(1)})">
              <polygon points="0,-7 5.5,5.5 0,2.8 -5.5,5.5" fill="${color}"/>
            </g>
            <rect x="13" y="-11" width="54" height="20" rx="5" fill="#ffffff" stroke="#dadce0" stroke-width="1.2"/>
            <text x="40" y="3" text-anchor="middle" fill="#202124" font-size="12" font-weight="700">${tr.id}</text>
          </g>`);
      });
    }

    this.svgEl.innerHTML = svgParts.join('');
  }
}

let towerGmap = null;
let carplayGmap = null;

function initGoogleRealtimeMaps() {
  towerGmap = new GoogleRealtimeSlippyMap({
    stageId: 'towerGmapStage',
    canvasId: 'towerVectorCanvas',
    tilesId: 'towerTilesContainer',
    svgId: 'towerOverlaySvg',
    centerLat: -20.8,
    centerLng: -46.8,
    zoom: 6,
    isCarPlay: false
  });

  const s0 = samplePolylineAtMeters(fleet[0].waypoints, fleet[0].arc, fleet[0].traveledMeters);
  carplayGmap = new GoogleRealtimeSlippyMap({
    stageId: 'carplayGmapStage',
    canvasId: 'carplayVectorCanvas',
    tilesId: 'carplayTilesContainer',
    svgId: 'carplayOverlaySvg',
    centerLat: s0.lat,
    centerLng: s0.lng,
    zoom: 15, // Nível de Rua / Avenida nítido por padrão!
    isCarPlay: true
  });

  towerGmap.render();
  carplayGmap.render();

  window.addEventListener('resize', () => {
    if (towerGmap) towerGmap.render();
    if (carplayGmap) carplayGmap.render();
  });
}

// Calcula em tempo real a Rua Atual e a Próxima Manobra do caminhão selecionado
function computeLiveNavigationTelemetry(tr) {
  let acc = 0;
  let currentStreet = tr.steps[0] ? tr.steps[0].road : tr.route;
  let nextStreet = tr.steps[1] ? tr.steps[1].road : tr.route;
  let distToNextTurnM = 450;

  for (let i = 0; i < tr.steps.length; i++) {
    const stepEnd = acc + tr.steps[i].dist;
    if (tr.traveledMeters < stepEnd) {
      currentStreet = tr.steps[i].road;
      nextStreet = tr.steps[i + 1] ? tr.steps[i + 1].road : tr.route.split('(')[0].trim();
      distToNextTurnM = Math.max(20, Math.round(stepEnd - tr.traveledMeters));
      break;
    }
    acc = stepEnd;
    if (i === tr.steps.length - 1) {
      currentStreet = tr.steps[i].road;
      nextStreet = tr.nextHubName;
      distToNextTurnM = Math.max(500, Math.round(tr.arc.totalMeters - tr.traveledMeters));
    }
  }

  const remKm = Math.max(1, Math.round(tr.totalRouteKm - tr.traveledMeters / 1000));
  const remMinsTotal = Math.max(5, Math.round((remKm / Math.max(50, tr.highwaySpeedKmh)) * 60));
  const h = Math.floor(remMinsTotal / 60);
  const m = remMinsTotal % 60;
  const timeFmt = h > 0 ? `${h} h ${m} min` : `${m} min`;
  const turnDistFmt = distToNextTurnM >= 1000 ? `${(distToNextTurnM / 1000).toFixed(1).replace('.', ',')} km` : `${distToNextTurnM} m`;

  return { currentStreet, nextStreet, turnDistFmt, remKm, timeFmt };
}

function updateLiveCabinTelemetryUI(tr) {
  const nav = computeLiveNavigationTelemetry(tr);
  const pos = samplePolylineAtMeters(tr.waypoints, tr.arc, tr.traveledMeters);

  document.getElementById('cpCurrentStreet').textContent =
    `Na via: ${nav.currentStreet} · ${tr.cityArea} (${pos.lat.toFixed(4)}, ${pos.lng.toFixed(4)})`;

  if (!state.riskActive || tr.id !== 'CAM-01') {
    document.getElementById('signDistText').textContent = nav.turnDistFmt;
    document.getElementById('signRoadCode').textContent = nav.nextStreet;
    document.getElementById('signRoadName').textContent = `Atual: ${nav.currentStreet}`;
    document.getElementById('gpsEta').textContent = `${nav.timeFmt} · ${nav.remKm} km · Chegada ${tr.etaClock}`;
  }
  document.getElementById('cpNextStopSub').textContent = `Rota: ${tr.route} · Parada: ${tr.nextHubName}`;
  document.getElementById('driverSpeedVal').textContent = String(Math.round(tr.liveSpeed));
}

// Opção de usar a localização GPS real do navegador do usuário
function useBrowserGeolocation() {
  if (!navigator.geolocation) {
    showToast('Geolocalização não suportada neste navegador.');
    return;
  }
  showToast('Obtendo sua localização GPS real com ruas e rotas...');
  navigator.geolocation.getCurrentPosition(
    async (position) => {
      const lat = position.coords.latitude;
      const lng = position.coords.longitude;
      const selTr = fleet.find((i) => i.id === state.selectedTruckId) || fleet[0];

      try {
        const destLat = lat + 0.08;
        const destLng = lng + 0.08;
        const url = `https://router.project-osrm.org/route/v1/driving/${lng},${lat};${destLng},${destLat}?overview=full&geometries=geojson&steps=true`;
        const res = await fetch(url);
        if (res.ok) {
          const data = await res.json();
          const r = data.routes[0];
          selTr.waypoints = r.geometry.coordinates.map(([lo, la]) => [la, lo]);
          selTr.arc = buildArcMetrics(selTr.waypoints);
          selTr.traveledMeters = 20;
          selTr.cityArea = 'Sua Localização GPS Real';
          selTr.steps = r.legs[0].steps.slice(0, 6).map((s) => ({
            road: s.name || 'Via Urbana Atual',
            dist: Math.max(60, Math.round(s.distance)),
            loc: [s.maneuver.location[1], s.maneuver.location[0]]
          }));
        }
      } catch (_) {
        selTr.waypoints.unshift([lat, lng]);
        selTr.arc = buildArcMetrics(selTr.waypoints);
        selTr.traveledMeters = 0;
      }

      state.followCarPlay = true;
      carplayGmap.setCenter(lat, lng, 16);
      towerGmap.setCenter(lat, lng, 13);
      updateLiveCabinTelemetryUI(selTr);
      showToast('GPS real sincronizado! Exibindo sua rua e trajeto em tempo real.');
    },
    () => {
      showToast('Permissão de GPS negada ou indisponível. Mantendo telemetria real da frota.');
    },
    { enableHighAccuracy: true, timeout: 8000 }
  );
}

// ==================== ROTEAMENTO CUSTOMIZADO NA TORRE ====================
async function fetchRoadRouteGeometry(originLatLng, destLatLng) {
  if (state.gmapsKey) {
    try {
      const res = await fetch('https://routes.googleapis.com/directions/v2:computeRoutes', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-Goog-Api-Key': state.gmapsKey,
          'X-Goog-FieldMask': 'routes.duration,routes.distanceMeters,routes.polyline.encodedPolyline'
        },
        body: JSON.stringify({
          origin: { location: { latLng: { latitude: originLatLng[0], longitude: originLatLng[1] } } },
          destination: { location: { latLng: { latitude: destLatLng[0], longitude: destLatLng[1] } } },
          travelMode: 'DRIVE',
          routingPreference: 'TRAFFIC_AWARE_OPTIMAL'
        })
      });
      if (res.ok) {
        const data = await res.json();
        if (data.routes && data.routes[0]) {
          const r = data.routes[0];
          return {
            coords: decodeGooglePolyline(r.polyline.encodedPolyline),
            km: Math.round(r.distanceMeters / 1000),
            mins: Math.round(parseInt(r.duration, 10) / 60),
            steps: null
          };
        }
      }
    } catch (_) {}
  }

  try {
    const q = `${originLatLng[1]},${originLatLng[0]};${destLatLng[1]},${destLatLng[0]}`;
    const res = await fetch(`https://router.project-osrm.org/route/v1/driving/${q}?overview=full&geometries=geojson&steps=true`);
    if (res.ok) {
      const data = await res.json();
      if (data.routes && data.routes[0]) {
        const r = data.routes[0];
        const raw = r.geometry.coordinates;
        const stride = Math.max(1, Math.floor(raw.length / 180));
        const coords = raw.filter((_, i) => i % stride === 0 || i === raw.length - 1).map(([lng, lat]) => [lat, lng]);
        const steps = r.legs[0].steps.filter((s) => s.distance > 80).slice(0, 8).map((s) => ({
          road: s.name || s.ref || 'Rodovia Federal',
          dist: Math.round(s.distance),
          loc: [s.maneuver.location[1], s.maneuver.location[0]]
        }));
        return { coords, km: Math.round(r.distance / 1000), mins: Math.round(r.duration / 60), steps };
      }
    }
  } catch (_) {}

  return { coords: fleet[0].baseWaypoints.slice(), km: 439, mins: 318, steps: null };
}

async function calculateCustomRealRoute() {
  const [origCoord, origLabel] = document.getElementById('routeOriginSelect').value.split('|');
  const [destCoord, destLabel] = document.getElementById('routeDestSelect').value.split('|');
  const o = origCoord.split(',').map(Number);
  const d = destCoord.split(',').map(Number);

  const selTr = fleet.find((i) => i.id === state.selectedTruckId) || fleet[0];
  showToast(`Traçando rota real para ${selTr.id}: ${origLabel} → ${destLabel}...`);

  const result = await fetchRoadRouteGeometry(o, d);
  const cost = calcRouteCost({
    km: result.km,
    dieselPrice: 6.1,
    baseKmL: selTr.kmL,
    loadTons: selTr.loadTons,
    maxTons: 30,
    toll: Math.round(result.km * 0.88),
    driverCost: Math.round((result.mins / 60) * 68)
  });

  selTr.waypoints = result.coords;
  selTr.arc = buildArcMetrics(selTr.waypoints);
  selTr.traveledMeters = 100;
  selTr.totalRouteKm = result.km;
  selTr.route = `${origLabel} → ${destLabel}`;
  selTr.cityArea = origLabel;
  selTr.costKm = cost.perKm;
  if (result.steps && result.steps.length) selTr.steps = result.steps;

  const h = Math.floor(result.mins / 60);
  const m = result.mins % 60;
  document.getElementById('gmapCardEta').textContent = `${h} h ${m} min (${result.km} km)`;
  document.getElementById('gmapCardVia').textContent = `${selTr.id}: ${origLabel} → ${destLabel} · R$ ${formatBRL(cost.perKm)}/km`;

  const midLat = (o[0] + d[0]) / 2;
  const midLng = (o[1] + d[1]) / 2;
  const distDeg = Math.hypot(o[0] - d[0], o[1] - d[1]);
  towerGmap.setCenter(midLat, midLng, distDeg > 12 ? 5 : distDeg > 5 ? 6 : 7);
  selectTruck(selTr.id);
}

