function allocateReturnFreight() {
  if (state.backhaulDone) return;
  state.backhaulDone = true;
  const cam04 = fleet.find((t) => t.id === 'CAM-04');
  cam04.status = 'optimal';
  cam04.cargoName = 'Alimentos Secos (Retorno IA)';
  cam04.loadTons = 18.0;
  cam04.costKm = 3.92;
  cam04.health = 'Retorno Alocado';
  cam04.aiNote = 'Carga de 18t alocada em Uberlândia (+R$ 6.400 líquidos)';
  cam04.hubNotice = 'Coleta confirmada na Doca B em Uberlândia (+R$ 6.400 líquidos garantidos).';

  state.savingsTotal += 6400;
  updateFleetKpis();
  populateTruckSelectors();

  document.getElementById('kpiBackhaul').textContent = '96,8%';
  document.getElementById('kpiBackhaulSub').textContent = 'Zero carretas vazias no corredor';
  document.getElementById('backhaulTag').textContent = 'Alocado';
  document.getElementById('backhaulTag').className = 'status-pill pill-emerald';
  const btn = document.getElementById('btnMatchBackhaul');
  btn.textContent = 'Carga Alocada no CAM-04 (Enviado ao Multimídia)';
  btn.disabled = true;

  selectTruck('CAM-04');
  focusSelectedTruckOnMap();
  showToast('Match de Retorno concluído: CAM-04 (Marcos Lima) atualizado com coleta em Uberlândia!');
}

function authorizeVucTransshipment() {
  if (state.vucDone) return;
  state.vucDone = true;
  const cam12 = fleet.find((t) => t.id === 'CAM-12');
  cam12.status = 'optimal';
  cam12.costKm = 3.84;
  cam12.health = '3 VUCs Alocados';
  cam12.aiNote = 'Baldeação confirmada no Hub Guarulhos (-22% R$/km)';
  cam12.hubNotice = '3 VUCs elétricos aguardando sua chegada na Doca 02 do Hub Guarulhos.';

  state.savingsTotal += 2950;
  updateFleetKpis();
  const btn = document.getElementById('btnAuthorizeVuc');
  btn.textContent = '3 VUCs Reservados na Doca 02 (Guarulhos)';
  btn.disabled = true;
  selectTruck('CAM-12');
  showToast('Baldeação confirmada para o CAM-12 (André Souza) no Hub Guarulhos.');
}

function toggleDayNightTheme() {
  const isDay = document.body.classList.toggle('theme-day');
  document.getElementById('themeBtnLabel').textContent = isDay ? 'Modo Noite' : 'Modo Sol';
}

function toggleSimulationSpeed() {
  const modes = [1, 5, 25, 0];
  const nextIdx = (modes.indexOf(state.simSpeed) + 1) % modes.length;
  state.simSpeed = modes[nextIdx];
  const labels = {
    1: 'Velocidade Frota: 1x (Real km/h)',
    5: 'Velocidade Frota: 5x',
    25: 'Velocidade Frota: 25x',
    0: 'Frota Pausada'
  };
  document.getElementById('simSpeedText').textContent = labels[state.simSpeed];
}

function ackDriverCard(btnId, text) {
  const tr = fleet.find((i) => i.id === state.selectedTruckId) || fleet[0];
  const btn = document.getElementById(btnId);
  btn.textContent = text;
  btn.disabled = true;
  tr.highwaySpeedKmh = tr.idealKmh;
  tr.liveSpeed = Math.min(tr.liveSpeed, tr.idealKmh);
  document.getElementById('driverSpeedVal').textContent = String(Math.round(tr.liveSpeed));
  showToast(`Ritmo ideal (${tr.idealKmh} km/h) aplicado ao ${tr.id} (${tr.driver}).`);
}

function speakDriverGuidance() {
  const tr = fleet.find((i) => i.id === state.selectedTruckId) || fleet[0];
  const nav = computeLiveNavigationTelemetry(tr);
  const msg = `Olá ${tr.driver}, caminhão ${tr.id}, placa ${tr.plate}. Você está em ${nav.currentStreet}. Em ${nav.turnDistFmt}, siga para ${nav.nextStreet}. ${tr.driverTip}`;
  if ('speechSynthesis' in window) {
    window.speechSynthesis.cancel();
    const u = new SpeechSynthesisUtterance(msg);
    u.lang = 'pt-BR';
    window.speechSynthesis.speak(u);
  }
  showToast(`Voz CarPlay (${tr.driver}): lendo rua atual e próxima manobra.`);
}

function toggleCameraExpand(camEl) {
  camEl.classList.toggle('expanded');
}

function updateClocks() {
  const now = new Date();
  const hh = String(now.getHours()).padStart(2, '0');
  const mm = String(now.getMinutes()).padStart(2, '0');
  const el = document.getElementById('cpClock');
  if (el) el.textContent = `${hh}:${mm}`;
}

let toastTimer;
function showToast(message) {
  const el = document.getElementById('sysToast');
  el.textContent = message;
  el.classList.remove('hidden');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => el.classList.add('hidden'), 4200);
}

// ==================== LOOP FÍSICO REALISTA EM METROS/SEGUNDO (dt real) ====================
let lastFrameTime = performance.now();
let lastUiTelemetrySync = 0;

function animateRealisticFleet(now) {
  const dt = Math.min(0.1, Math.max(0.001, (now - lastFrameTime) / 1000));
  lastFrameTime = now;

  if (state.simSpeed > 0) {
    fleet.forEach((tr) => {
      // Define velocidade alvo realista conforme o trecho (via urbana vs rodovia expressa)
      const isUrbanAccess = tr.traveledMeters < 2200;
      const targetKmh = isUrbanAccess ? tr.urbanSpeedKmh : tr.highwaySpeedKmh;
      tr.liveSpeed += (targetKmh - tr.liveSpeed) * Math.min(1, dt * 1.2);

      // Avança exatamente os metros correspondentes a (km/h / 3.6) * dt
      const metersDelta = (tr.liveSpeed / 3.6) * state.simSpeed * dt * tr.direction;
      tr.traveledMeters += metersDelta;

      if (tr.traveledMeters >= tr.arc.totalMeters - 20) {
        tr.traveledMeters = tr.arc.totalMeters - 25;
        tr.direction = -1;
      } else if (tr.traveledMeters <= 20) {
        tr.traveledMeters = 25;
        tr.direction = 1;
      }

      const sample = samplePolylineAtMeters(tr.waypoints, tr.arc, tr.traveledMeters);
      const desiredHeading = tr.direction === 1 ? sample.heading : (sample.heading + 180) % 360;
      tr.smoothHeading = lerpAngle(tr.smoothHeading, desiredHeading, Math.min(1, dt * 4.5));
    });

    const selTr = fleet.find((i) => i.id === state.selectedTruckId) || fleet[0];
    const selPos = samplePolylineAtMeters(selTr.waypoints, selTr.arc, selTr.traveledMeters);

    if (now - lastUiTelemetrySync > 450) {
      updateLiveCabinTelemetryUI(selTr);
      lastUiTelemetrySync = now;
    }

    if (towerGmap && state.mainView === 'tower') {
      if (state.followTower) {
        towerGmap.centerLat = selPos.lat;
        towerGmap.centerLng = selPos.lng;
      }
      towerGmap.render();
    }

    if (carplayGmap && state.mainView === 'driver' && (state.carplayApp === 'split' || state.carplayApp === 'map')) {
      if (state.followCarPlay) {
        carplayGmap.centerLat = selPos.lat;
        carplayGmap.centerLng = selPos.lng;
      }
      carplayGmap.render();
    }

    state.dashOffset = (state.dashOffset - 18 * dt * state.simSpeed) % 18;
    document.querySelectorAll('.road-dash-line').forEach((line) => {
      line.setAttribute('stroke-dashoffset', state.dashOffset.toFixed(1));
    });
  }

  requestAnimationFrame(animateRealisticFleet);
}

function initSystem() {
  mountIcons();
  populateTruckSelectors();
  renderPartsList();
  selectPart('engine');
  updateFleetKpis();
  initGoogleRealtimeMaps();
  selectTruck('CAM-01');
  document.getElementById('simSpeedText').textContent = 'Velocidade Frota: 1x (Real km/h)';
  updateClocks();
  setInterval(updateClocks, 10000);
  lastFrameTime = performance.now();
  requestAnimationFrame(animateRealisticFleet);
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initSystem);
} else {
  initSystem();
}
